// Rust port of tests/test7.cpp (mapbox earcut spiral triangulation test).
//
// Mirrors the C++ program:
//   - builds a spiral polygon with `2 * n` points (default n = 7),
//   - triangulates it with the earcut algorithm,
//   - prints the resulting indices separated by spaces.

mod earcut;

use std::io::Write;

/// Replicates C `std::atoi`: skips leading whitespace, accepts an optional
/// sign, then consumes digits until the first non-digit; returns 0 if none.
fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }
    let mut sign: i64 = 1;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        if bytes[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    let mut val: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        val = val.wrapping_mul(10).wrapping_add((bytes[i] - b'0') as i64);
        i += 1;
    }
    (sign.wrapping_mul(val)) as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut n: i32 = 7;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let mut spiral: Vec<[f64; 2]> = Vec::new();
    let mut i: i32 = 0;
    while i < n.wrapping_mul(2) {
        let t = f64::from(i) / f64::from(n.wrapping_mul(2));
        let radius = t;
        let angle = 4.0 * std::f64::consts::PI * t;
        spiral.push([radius * angle.cos(), radius * angle.sin()]);
        i += 1;
    }

    let polygon: Vec<Vec<[f64; 2]>> = vec![spiral];

    let indices = earcut::earcut(&polygon);

    // std::cout << idx << " " for each index (trailing space, no newline)
    let mut out = String::new();
    for idx in indices {
        out.push_str(&idx.to_string());
        out.push(' ');
    }
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(out.as_bytes());
}

