// Pure-Rust reimplementation of the mapbox earcut polygon triangulation
// algorithm (ear clipping with a z-order curve hash for large polygons).
//
// The original C++ uses raw pointers to `Node`; this port stores nodes in an
// arena (`Vec<Node>`) and links them by index, which preserves the exact
// iteration/linkage semantics of the pointer-based original. Removed nodes
// are only unlinked, never freed, matching the original's object pool.

pub type Point = [f64; 2];

/// Null sentinel for node links (replaces C++ nullptr).
const NULL: usize = usize::MAX;

struct Node {
    i: u32, // vertex index in the source polygon
    x: f64,
    y: f64,
    prev: usize,
    next: usize,
    z: i32, // z-order curve value
    prev_z: usize,
    next_z: usize,
}

pub struct Earcut {
    pub indices: Vec<u32>,
    nodes: Vec<Node>,
    hashing: bool,
    min_x: f64,
    min_y: f64,
    inv_size: f64,
}

/// Triangulate a polygon given as a list of rings (outer ring first).
/// Returns a flat list of triangle vertex indices.
pub fn earcut(polygon: &[Vec<Point>]) -> Vec<u32> {
    let mut e = Earcut::new();
    e.run(polygon);
    e.indices
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            indices: Vec::new(),
            nodes: Vec::new(),
            hashing: false,
            min_x: 0.0,
            min_y: 0.0,
            inv_size: 0.0,
        }
    }

    pub fn run(&mut self, points: &[Vec<Point>]) {
        self.indices.clear();
        self.nodes.clear();

        if points.is_empty() {
            return;
        }

        let threshold: i64 = 80;
        let mut len: usize = 0;
        for ring in points {
            len += ring.len();
        }

        let outer_node = match self.linked_list(&points[0], true) {
            Some(node) => node,
            None => return,
        };
        if self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        // (Hole linking is omitted: this port targets hole-free polygons.)

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = threshold < (len * 2) as i64;
        if self.hashing {
            let mut max_x: u64 = 2;
            let mut max_y: u64 = 2;
            self.min_x = f64::MAX;
            self.min_y = f64::MAX;
            for p in &points[0] {
                let x = p[0];
                let y = p[1];
                self.min_x = self.min_x.min(x);
                self.min_y = self.min_y.min(y);
                max_x = (max_x as f64).max(x) as u64;
                max_y = (max_y as f64).max(y) as u64;
            }

            // min_x, min_y and inv_size are later used to transform coords
            // into integers for z-order calculation
            self.inv_size = (max_x as f64 - self.min_x).max(max_y as f64 - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);
    }

    // create a node and push it into the arena
    fn create_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node {
            i,
            x,
            y,
            prev: NULL,
            next: NULL,
            z: 0,
            prev_z: NULL,
            next_z: NULL,
        });
        self.nodes.len() - 1
    }

    // create a node and optionally link it in a circular list (after `last`)
    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: usize) -> usize {
        let p = self.create_node(i, x, y);
        if last == NULL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let last_next = self.nodes[last].next;
            self.nodes[p].next = last_next;
            self.nodes[p].prev = last;
            self.nodes[last_next].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        if self.nodes[p].prev_z != NULL {
            let prev_z = self.nodes[p].prev_z;
            self.nodes[prev_z].next_z = self.nodes[p].next_z;
        }
        if self.nodes[p].next_z != NULL {
            let next_z = self.nodes[p].next_z;
            self.nodes[next_z].prev_z = self.nodes[p].prev_z;
        }
    }

    // create a circular doubly linked list from a ring in the specified winding order
    fn linked_list(&mut self, points: &[Point], clockwise: bool) -> Option<usize> {
        let len = points.len();
        let mut sum: f64 = 0.0;
        let mut j = if len > 0 { len - 1 } else { 0 };

        // calculate original winding order of a polygon ring
        for i in 0..len {
            let p1 = points[i];
            let p2 = points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
        }

        // link points into circular doubly-linked list in the specified winding order
        let mut last = NULL;
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(i as u32, points[i][0], points[i][1], last);
            }
        } else {
            let mut i = len;
            while i > 0 {
                i -= 1;
                last = self.insert_node(i as u32, points[i][0], points[i][1], last);
            }
        }

        if last != NULL && self.equals(last, self.nodes[last].next) {
            self.remove_node(last);
            last = self.nodes[last].next;
        }

        if last == NULL {
            None
        } else {
            Some(last)
        }
    }

    // eliminate colinear or duplicate points
    fn filter_points(&mut self, start: usize, mut end: usize) -> usize {
        if end == NULL {
            end = start;
        }

        let mut p = start;
        loop {
            let mut again = false;

            if self.equals(p, self.nodes[p].next)
                || self.area(self.nodes[p].prev, p, self.nodes[p].next) == 0.0
            {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    // main ear slicing loop which triangulates a polygon (given as a linked list)
    fn earcut_linked(&mut self, ear: usize, pass: i32) {
        if ear == NULL {
            return;
        }
        let mut ear = ear;

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = self.nodes[next].next;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any more ears
            if ear == stop {
                // try filtering points and slicing again
                if pass == 0 {
                    let filtered = self.filter_points(ear, NULL);
                    self.earcut_linked(filtered, 1);

                // if this didn't work, try curing all small self-intersections locally
                } else if pass == 1 {
                    let filtered = self.filter_points(ear, NULL);
                    let cured = self.cure_local_intersections(filtered);
                    self.earcut_linked(cured, 2);

                // as a last resort, try splitting the remaining polygon into two
                } else if pass == 2 {
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    // check whether a polygon node forms a valid ear with adjacent nodes
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[self.nodes[ear].next].next;

        while p != self.nodes[ear].prev {
            if point_in_triangle(
                self.nodes[a].x,
                self.nodes[a].y,
                self.nodes[b].x,
                self.nodes[b].y,
                self.nodes[c].x,
                self.nodes[c].y,
                self.nodes[p].x,
                self.nodes[p].y,
            ) && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = ax.min(bx).min(cx);
        let min_ty = ay.min(by).min(cy);
        let max_tx = ax.max(bx).max(cx);
        let max_ty = ay.max(by).max(cy);

        // z-order range for the current triangle bbox;
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;

        while p != NULL && self.nodes[p].z <= max_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && point_in_triangle(
                    ax,
                    ay,
                    bx,
                    by,
                    cx,
                    cy,
                    self.nodes[p].x,
                    self.nodes[p].y,
                )
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;

        while p != NULL && self.nodes[p].z >= min_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && point_in_triangle(
                    ax,
                    ay,
                    bx,
                    by,
                    cx,
                    cy,
                    self.nodes[p].x,
                    self.nodes[p].y,
                )
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    // go through all polygon nodes and cure small local self-intersections
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut p = start;
        let mut start = start;
        loop {
            let a = self.nodes[p].prev;
            let b = self.nodes[self.nodes[p].next].next;

            // a self-intersection where edge (v[i-1],v[i]) intersects (v[i+1],v[i+2])
            if !self.equals(a, b)
                && self.intersects(a, p, self.nodes[p].next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                self.remove_node(p);
                let p_next = self.nodes[p].next;
                self.remove_node(p_next);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, NULL)
    }

    // try splitting polygon into two and triangulate them independently
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    a = self.filter_points(a, self.nodes[a].next);
                    let c = self.filter_points(c, self.nodes[c].next);

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    // link two polygon vertices with a bridge
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.create_node(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let b2 = self.create_node(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    // interlink polygon nodes in z-order
    fn index_curve(&mut self, start: usize) {
        let mut p = start;

        loop {
            if self.nodes[p].z == 0 {
                self.nodes[p].z = self.z_order(self.nodes[p].x, self.nodes[p].y);
            }
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let prev_z = self.nodes[p].prev_z;
        self.nodes[prev_z].next_z = NULL;
        self.nodes[p].prev_z = NULL;

        self.sort_linked(p);
    }

    // Simon Tatham's linked list merge sort algorithm
    // http://www.chiark.greenend.org.uk/~sgtatham/algorithms/listsort.html
    fn sort_linked(&mut self, list: usize) -> usize {
        let mut list = list;
        let mut in_size = 1usize;

        loop {
            let mut p = list;
            list = NULL;
            let mut tail = NULL;
            let mut num_merges = 0;

            while p != NULL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NULL {
                        break;
                    }
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NULL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NULL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NULL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NULL;

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }

    // z-order of a vertex given coords, size of the data side and minimum extent
    fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF_00FF;
        x = (x | (x << 4)) & 0x0F0F_0F0F;
        x = (x | (x << 2)) & 0x3333_3333;
        x = (x | (x << 1)) & 0x5555_5555;

        y = (y | (y << 8)) & 0x00FF_00FF;
        y = (y | (y << 4)) & 0x0F0F_0F0F;
        y = (y | (y << 2)) & 0x3333_3333;
        y = (y | (y << 1)) & 0x5555_5555;

        x | (y << 1)
    }

    // check if a diagonal between two polygon nodes is valid (lies in polygon interior)
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        self.nodes[self.nodes[a].next].i != self.nodes[b].i
            && self.nodes[self.nodes[a].prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(self.nodes[a].prev, a, self.nodes[b].prev) != 0.0
                    || self.area(a, self.nodes[b].prev, b) != 0.0))
                || (self.equals(a, b)
                    && self.area(self.nodes[a].prev, a, self.nodes[a].next) > 0.0
                    && self.area(self.nodes[b].prev, b, self.nodes[b].next) > 0.0))
    }

    // signed area of a triangle
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (self.nodes[q].y - self.nodes[p].y) * (self.nodes[r].x - self.nodes[q].x)
            - (self.nodes[q].x - self.nodes[p].x) * (self.nodes[r].y - self.nodes[q].y)
    }

    // check if two points are equal
    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    // check if two segments intersect
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        if (self.equals(p1, q1) && self.equals(p2, q2))
            || (self.equals(p1, q2) && self.equals(p2, q1))
        {
            return true;
        }
        (orient2d(
            self.nodes[p1].x,
            self.nodes[p1].y,
            self.nodes[q1].x,
            self.nodes[q1].y,
            self.nodes[p2].x,
            self.nodes[p2].y,
        ) > 0.0)
            != (orient2d(
                self.nodes[p1].x,
                self.nodes[p1].y,
                self.nodes[q1].x,
                self.nodes[q1].y,
                self.nodes[q2].x,
                self.nodes[q2].y,
            ) > 0.0)
            && (orient2d(
                self.nodes[p2].x,
                self.nodes[p2].y,
                self.nodes[q2].x,
                self.nodes[q2].y,
                self.nodes[p1].x,
                self.nodes[p1].y,
            ) > 0.0)
                != (orient2d(
                    self.nodes[p2].x,
                    self.nodes[p2].y,
                    self.nodes[q2].x,
                    self.nodes[q2].y,
                    self.nodes[q1].x,
                    self.nodes[q1].y,
                ) > 0.0)
    }

    // check if a polygon diagonal intersects any polygon segments
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[self.nodes[p].next].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[self.nodes[p].next].i != self.nodes[b].i
                && self.intersects(p, self.nodes[p].next, a, b)
            {
                return true;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }

        false
    }

    // check if a polygon diagonal is locally inside the polygon
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        if self.area(self.nodes[a].prev, a, self.nodes[a].next) < 0.0 {
            self.area(a, b, self.nodes[a].next) >= 0.0
                && self.area(a, self.nodes[a].prev, b) >= 0.0
        } else {
            self.area(a, b, self.nodes[a].prev) < 0.0
                || self.area(a, self.nodes[a].next, b) < 0.0
        }
    }

    // check if the middle vertex of a polygon diagonal is inside the polygon
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let p_next = self.nodes[p].next;
            if ((self.nodes[p].y > py) != (self.nodes[p_next].y > py))
                && self.nodes[p_next].y != self.nodes[p].y
                && px < (self.nodes[p_next].x - self.nodes[p].x) * (py - self.nodes[p].y)
                    / (self.nodes[p_next].y - self.nodes[p].y)
                    + self.nodes[p].x
            {
                inside = !inside;
            }
            p = p_next;
            if p == a {
                break;
            }
        }

        inside
    }
}

// check if a point lies within a convex triangle
fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) >= (ax - px) * (cy - py)
        && (ax - px) * (by - py) >= (bx - px) * (ay - py)
        && (bx - px) * (cy - py) >= (cx - px) * (by - py)
}

fn orient2d(ax: f64, ay: f64, bx: f64, by: f64, cx: f64, cy: f64) -> f64 {
    (ay - cy) * (bx - cx) - (ax - cx) * (by - cy)
}
